/* ==UserStyle==
@name           RP Bastion — Valkyrie Arcane Sanctuary
@namespace      rp-bastion-valkyrie-arcane-sanctuary
@version        1.2.7
@description    Epic arcane sanctuary with the new RP Bastion banner and original navigation, plus Valkyrie side ornaments and mystical title frames. All artwork embedded.
@author         TBotM (Zonetrix)
@license        CC0-1.0
@preprocessor   default
==/UserStyle== */

/* INSTALL: Disable ALL other RP Bastion themes first. This is a standalone theme. Import this entire
   file into Stylus as a UserCSS style, then save and refresh the forum.

   This is a sculpted-surface reskin for the phpBB2 selectors in the supplied theme.
   No typography or spacing resets are used for post content.
   The header welcome line has its own larger decorative serif styling.
   Desktop outer-frame width is adjusted to expose the decorative side gutters.
   BBCode colours and formatting inside posts are left intact. Dark authored
   text may still be difficult to read, just as with any dark forum theme.
   No external images, fonts, scripts, tracking or network assets are loaded.
*/

@-moz-document domain("rpbastion.forumotion.com") {
  :root {
    /* Palette inspired by the supplied RP Bastion banner and Valkyrie logo.
       Accents are lightened for legibility on the dark surfaces. */
    --rpb-night:       #04090d;
    --rpb-shell:       #090f16;
    --rpb-panel:       #101923;
    --rpb-panel-alt:   #14212e;
    --rpb-raised:      #1b2938;
    --rpb-ocean:       #005d85;
    --rpb-ocean-deep:  #07304a;
    --rpb-line:        #374858;
    --rpb-silver:      #a995af;
    --rpb-text:        #F3E4FF;
    --rpb-muted:       #b8b2c3;
    --rpb-link:        #79c9ed;
    --rpb-visited:     #c6afd6;
    --rpb-magenta:     #a91d6b;
    --rpb-hover:       #f2a5d1;
    --rpb-focus:       #98ddff;
    --rpb-field:       #080f18;
  }

  /* Page and outer frame; the banner replacement is scoped to #i_logo below. */
  body {
    background-color: var(--rpb-night) !important;
    background-image:
      radial-gradient(ellipse at top left, #005d8533, transparent 55%),
      radial-gradient(ellipse at top right, #a91d6b14, transparent 45%) !important;
    color: var(--rpb-text) !important;
  }

  td.bodyline {
    background-color: var(--rpb-shell) !important;
    background-image: none !important;
    border-color: var(--rpb-line) !important;
  }

  /* Exclude authored tables inside posts, quotes and signatures. */
  :is(.forumline, table.thHead):not(.postbody *, .signature *, .quote *) {
    background-color: var(--rpb-shell) !important;
    border-color: var(--rpb-line) !important;
  }

  td:is(.row1, .row3, .row3Right):not(.postbody *, .signature *, .quote *) {
    background-color: var(--rpb-panel) !important;
    background-image: none !important;
    border-color: var(--rpb-line) !important;
    color: var(--rpb-text) !important;
  }

  td.row2:not(.postbody *, .signature *, .quote *) {
    background-color: var(--rpb-panel-alt) !important;
    background-image: none !important;
    border-color: var(--rpb-line) !important;
    color: var(--rpb-text) !important;
  }

  td.spaceRow {
    background-color: var(--rpb-shell) !important;
    background-image: none !important;
    border-color: var(--rpb-line) !important;
  }

  /* Ocean-blue section headers; muted lavender category strips. */
  :is(.forumline > tbody > tr > th, .forumline > tr > th,
      th.thHead, th.thSides, th.thLeft, th.thRight, th.thBottom,
      th.thTop, th.thCornerL, th.thCornerR, td.thTop):not(.postbody *, .signature *, .quote *) {
    background-color: var(--rpb-ocean-deep) !important;
    background-image: linear-gradient(110deg, #07304a, #005374 65%, #172337) !important;
    border-color: #466079 !important;
    color: #f0eaf4 !important;
  }

  td:is(.cat, .catHead, .catBottom, .catSides, .catLeft, .catRight, .rowpic):not(.postbody *, .signature *, .quote *) {
    background-color: #211d2a !important;
    background-image: linear-gradient(100deg, #282332, #172537 70%, #281b2b) !important;
    border-color: #66556f !important;
    color: #e0d2e7 !important;
  }

  :is(.maintitle, .cattitle):not(.postbody *, .signature *) {
    color: #d5c2df !important;
  }

  :is(.gen, .genmed, .gensmall, .name, .nav, .postdetails, .copyright):not(a, .postbody, .postbody *, .signature, .signature *, .quote, .quote *) {
    color: var(--rpb-muted) !important;
  }

  /* Set only the post container's default ink. Never target its descendants
     with a blanket reset: italics, bold, sizes and BBCode colours survive. */
  .postbody { color: var(--rpb-text) !important; }

  /* UI links. Authored post/signature links retain their own styling. */
  a:link:not(.postbody *, .signature *, .quote *) {
    color: var(--rpb-link) !important;
  }
  a:visited:not(.postbody *, .signature *, .quote *) {
    color: var(--rpb-visited) !important;
  }
  a:hover:not(.postbody *, .signature *, .quote *) {
    color: var(--rpb-hover) !important;
  }
  a:active:not(.postbody *, .signature *, .quote *) {
    color: #ffffff !important;
  }

  /* Low-specificity defaults improve plain post links while letting author
     inline colours and more specific site rules win. */
  :where(.postbody, .signature, .quote) :where(a:link) { color: var(--rpb-link); }
  :where(.postbody, .signature, .quote) :where(a:visited) { color: var(--rpb-visited); }
  :where(.postbody, .signature, .quote) :where(a:hover) { color: var(--rpb-hover); }

  .quote {
    background-color: #1b202e !important;
    background-image: none !important;
    border-color: var(--rpb-silver) !important;
    color: #ded5e6 !important;
  }
  .code {
    background-color: #08151f !important;
    background-image: none !important;
    border-color: #426b83 !important;
    color: #b1def0 !important;
  }
  hr { border-color: var(--rpb-line) !important; }

  /* Inputs keep native sizing, font, padding and control appearance. */
  :is(textarea, select,
      input:not([type]), input[type="text"], input[type="password"],
      input[type="email"], input[type="search"], input[type="url"],
      input[type="number"], input[type="tel"]) {
    background-color: var(--rpb-field) !important;
    background-image: none !important;
    border-color: #586277 !important;
    color: var(--rpb-text) !important;
    caret-color: var(--rpb-focus) !important;
    color-scheme: dark;
  }
  :is(input, textarea)::placeholder { color: var(--rpb-muted) !important; }

  :is(button, input[type="button"], input[type="submit"], input[type="reset"],
      input.mainoption, input.liteoption) {
    background-color: var(--rpb-ocean-deep) !important;
    background-image: linear-gradient(#17405b, #10283d) !important;
    border-color: #63839a !important;
    color: #f2edf5 !important;
  }
  :is(button, input[type="button"], input[type="submit"], input[type="reset"],
      input.mainoption, input.liteoption):hover:not(:disabled) {
    background-color: #392339 !important;
    background-image: linear-gradient(#473047, #281e31) !important;
    border-color: var(--rpb-hover) !important;
  }
  :is(input[type="checkbox"], input[type="radio"]) {
    accent-color: var(--rpb-magenta);
  }
  :is(a, button, input, textarea, select):focus-visible {
    outline: 2px solid var(--rpb-focus) !important;
    outline-offset: 2px !important;
  }

  /* SCEditor chrome, where present. Leave toolbar icons and the editable
     iframe alone so buttons, emoticons and rich-text formatting still work. */
  :is(.sceditor-container, .sceditor-toolbar, .sceditor-group,
      .sceditor-dropdown) {
    background-color: var(--rpb-raised) !important;
    border-color: var(--rpb-line) !important;
    color: var(--rpb-text) !important;
  }

  /* currentColor preserves each selected element's original text colour.
     Apply directly to descendants too, including nested BBCode spans. */
  ::selection {
    background-color: #34475f !important;
    color: currentColor !important;
    text-shadow: none !important;
  }
  .postbody::selection,
  .postbody *::selection,
  .quote::selection,
  .quote *::selection,
  .signature::selection,
  .signature *::selection {
    background-color: #34475f !important;
    color: currentColor !important;
    text-shadow: none !important;
  }

  /* ================================================================
     VALKYRIE 3D — decorative depth without changing the box model.
     Shadows create bevels without adding borders, padding or dimensions.
     Reading surfaces stay matte; images and authored layouts stay intact.
     ================================================================ */

  td.bodyline {
    border-radius: 12px !important;
    box-shadow:
      inset 0 1px 0 #d6c3e04d,
      inset 1px 0 0 #86c7ea1a,
      inset 0 -1px 0 #000000cc,
      0 14px 38px #00000080 !important;
  }

  :is(.forumline, table.thHead):not(.postbody *, .signature *, .quote *) {
    border-radius: 8px !important;
    box-shadow:
      0 1px 0 #adc1d126,
      0 5px 12px #00000066,
      inset 0 1px 0 #ffffff12 !important;
  }

  td:is(.row1, .row2, .row3, .row3Right):not(.postbody *, .signature *, .quote *) {
    box-shadow: inset 0 1px 0 #c7dcf00b, inset 0 -1px 0 #00000040 !important;
  }

  :is(.forumline > tbody > tr > th, .forumline > tr > th,
      th.thHead, th.thSides, th.thLeft, th.thRight, th.thBottom,
      th.thTop, th.thCornerL, th.thCornerR, td.thTop):not(.postbody *, .signature *, .quote *) {
    background-image:
      linear-gradient(115deg, #93d9ff14, transparent 42%, #c5a7d510),
      linear-gradient(to bottom, #246888 0%, #124864 46%, #0c354e 49%, #09283d 100%) !important;
    border-color: #50677c !important;
    box-shadow:
      inset 0 1px 0 #c8edff66,
      inset 0 2px 0 #ffffff0d,
      inset 0 -2px 0 #020911b3 !important;
    text-shadow: 0 1px 2px #000000b3 !important;
  }

  td:is(.cat, .catHead, .catBottom, .catSides, .catLeft, .catRight, .rowpic):not(.postbody *, .signature *, .quote *) {
    background-image:
      repeating-linear-gradient(0deg, #d7c4e004 0, #d7c4e004 1px, transparent 1px, transparent 3px),
      linear-gradient(110deg, #ad97b51a, transparent 45%, #007ca31a),
      linear-gradient(to bottom, #40364b, #292636 48%, #201f2e 51%, #181e2b) !important;
    box-shadow:
      inset 0 1px 0 #d6c3e066,
      inset 0 -2px 0 #060810cc,
      inset 3px 0 0 #a995af99 !important;
    text-shadow: 0 1px 2px #000000b3 !important;
  }

  /* Navigation gets a subtle bevel without altering its wrapping or size. */
  a.mainmenu:not(.postbody *, .signature *, .quote *) {
    background-color: #162533 !important;
    background-image: linear-gradient(#2a3a4b, #152332) !important;
    border-radius: 5px !important;
    box-shadow: inset 0 1px 0 #d8c7e033, inset 0 -1px 0 #000000b3, 0 2px 3px #00000040 !important;
  }
  a.mainmenu:hover:not(.postbody *, .signature *, .quote *) {
    background-image: linear-gradient(#493247, #272134) !important;
    box-shadow: inset 0 1px 0 #f2a5d166, inset 0 -1px 0 #000000b3, 0 0 7px #a91d6b33 !important;
  }
  a.mainmenu:active:not(.postbody *, .signature *, .quote *) {
    box-shadow: inset 0 2px 4px #00000099, inset 0 -1px 0 #d6c3e026 !important;
  }

  :is(button, input[type="button"], input[type="submit"], input[type="reset"],
      input.mainoption, input.liteoption) {
    border-radius: 6px !important;
    background-image: linear-gradient(#35617b, #1d425c 48%, #16344c 51%, #10283b) !important;
    box-shadow: inset 0 1px 0 #c7eaff66, inset 0 -1px 0 #00000099, 0 3px 5px #00000059 !important;
    text-shadow: 0 1px 1px #00000099 !important;
  }
  :is(button, input[type="button"], input[type="submit"], input[type="reset"],
      input.mainoption, input.liteoption):hover:not(:disabled) {
    background-image: linear-gradient(#62415d, #3e2b42 48%, #302335 51%, #211c2c) !important;
    box-shadow: inset 0 1px 0 #ffd0eb66, inset 0 -1px 0 #00000099, 0 3px 7px #00000066, 0 0 8px #a91d6b26 !important;
  }
  :is(button, input[type="button"], input[type="submit"], input[type="reset"],
      input.mainoption, input.liteoption):active:not(:disabled) {
    background-image: linear-gradient(#101c2a, #1c3043) !important;
    box-shadow: inset 0 2px 5px #000000b3, inset 0 -1px 0 #bdcce033 !important;
  }
  :is(button, input[type="button"], input[type="submit"], input[type="reset"]):disabled {
    box-shadow: inset 0 1px 2px #00000066 !important;
    color: var(--rpb-muted) !important;
  }

  :is(textarea, select,
      input:not([type]), input[type="text"], input[type="password"],
      input[type="email"], input[type="search"], input[type="url"],
      input[type="number"], input[type="tel"]) {
    border-radius: 6px !important;
    box-shadow: inset 0 2px 5px #00000099, 0 1px 0 #d3c1e026 !important;
  }
  :is(textarea, select,
      input:not([type]), input[type="text"], input[type="password"],
      input[type="email"], input[type="search"], input[type="url"],
      input[type="number"], input[type="tel"]):focus {
    border-color: var(--rpb-focus) !important;
    box-shadow: inset 0 2px 5px #00000080, 0 0 8px #79c9ed33 !important;
  }

  .quote {
    border-radius: 6px !important;
    box-shadow: inset 3px 0 0 #a995af99, inset 0 2px 5px #00000059, 0 1px 0 #d6c3e01a !important;
  }
  .code {
    border-radius: 5px !important;
    box-shadow: inset 0 2px 5px #00000080, 0 1px 0 #79c9ed26 !important;
  }
  .sceditor-container {
    border-radius: 8px !important;
    box-shadow: 0 4px 12px #00000066, inset 0 1px 0 #c8d9ed26 !important;
  }
  .sceditor-toolbar {
    box-shadow: inset 0 1px 0 #d6c3e026, inset 0 -1px 0 #00000080 !important;
  }
  /* No animation or transforms: depth remains steady when reading or typing.
     No overflow clipping: menus, editor popups and focus rings stay visible. */

  /* ARCANE ARTWORK EDITION — built-in image generation.
     Side-art prompt: PBR Valkyrie wing armour and obsidian shards at the
     outer edges; empty black centre; silver-lavender, blue crystals and
     restrained magenta runes. No lettering, people or interface.
     Title-art prompt: wide engraved obsidian plaque with mystical metallic
     feather borders, blue filigree and magenta accents; dark clear centre.

     Images are embedded directly in background-image declarations.
     Large data URLs are deliberately NOT stored in CSS custom properties.
     No third-party asset requests.
     To widen/narrow desktop ornament gutters, change --rpb-art-gutter.
     A fixed background follows the viewport; no animated effects.
  */
  :root {
    --rpb-art-gutter: clamp(90px, 10vw, 210px);
  }

  body {
    background-color: var(--rpb-night) !important;
    background-image: url("data:image/png;base64,") !important;
    background-position: center top !important;
    background-size: 100% 100vh !important;
    background-repeat: no-repeat !important;
    background-attachment: fixed !important;
  }

  /* phpBB2 outer wrapper only; never resize post tables or their contents.
     Both tbody and direct-tr forms are handled. The inherited site layout
     is used if a different wrapper structure is present. */
  @media (min-width: 1280px) {
    body > table:has(> tbody > tr > td.bodyline),
    body > table:has(> tr > td.bodyline) {
      width: calc(100% - var(--rpb-art-gutter) - var(--rpb-art-gutter)) !important;
      margin-left: auto !important;
      margin-right: auto !important;
    }
  }

  /* Fit the entire engraved frame to each title bar, so its top and bottom
     ornament stays visible. The dark central band remains behind the text. */
  :is(.forumline > tbody > tr > th, .forumline > tr > th,
      th.thHead, th.thSides, th.thLeft, th.thRight, th.thBottom,
      th.thTop, th.thCornerL, th.thCornerR, td.thTop):not(.postbody *, .signature *, .quote *),
  td:is(.cat, .catHead, .catBottom, .catSides, .catLeft, .catRight, .rowpic):not(.postbody *, .signature *, .quote *) {
    background-color: #07101b !important;
    background-image: linear-gradient(#03071026, #03071026), url("data:image/png;base64,") !important;
    background-position: center !important;
    background-size: 100% 100% !important;
    background-repeat: no-repeat !important;
    border-color: #897591 !important;
    color: #f1e9f5 !important;
    text-shadow: 0 1px 3px #000, 0 0 5px #000 !important;
    box-shadow: inset 0 1px 0 #d6c3e04d, inset 0 -1px 0 #000000b3 !important;
  }

  @media (max-width: 1279px) {
    body {
      background-image: radial-gradient(ellipse at top, #07304a, #04090d 75%) !important;
      background-attachment: scroll !important;
    }
  }

  /* ARCANE SANCTUARY MASTHEAD — v1.1.0
     Generated with the built-in image tool: epic mysterious obsidian ruins,
     silver-lavender Valkyrie carvings, blue crystal rings and subtle magenta
     magic; dark central space for the original logo and navigation.

     The artwork decorates the top of the existing bodyline, so it does not
     depend on guessed logo IDs or change any links, buttons or post layout.
     Direct image embedding preserves the working v1.0.1 approach.
     Adjust this small height variable if your header height differs.
  */
  :root { --rpb-masthead-height: 600px; }

  td.bodyline {
    background-color: var(--rpb-shell) !important;
    background-image:
      linear-gradient(to bottom, transparent 0%, transparent 78%, #090f16 100%),
      url("data:image/png;base64,") !important;
    background-size: 100% var(--rpb-masthead-height), 100% var(--rpb-masthead-height) !important;
    background-position: center top, center top !important;
    background-repeat: no-repeat, no-repeat !important;
    background-attachment: scroll, scroll !important;
  }

  /* A restrained dark backing keeps navigation legible above the scene.
     Existing graphical buttons, labels, link destinations and spacing stay. */
  td.bodyline .mainmenu:not(.postbody *, .signature *, .quote *) {
    text-shadow: 0 1px 3px #000, 0 0 5px #000 !important;
  }

  @media (max-width: 900px) {
    td.bodyline {
      /* Preserve the architecture's proportions when the viewport narrows. */
      background-size: 100% var(--rpb-masthead-height), auto var(--rpb-masthead-height) !important;
    }
  }

  /* WELCOME LINE — phpBB2 masthead description, not post text.
     Limit to the first direct header table and exclude links, images,
     navigation, authored post bodies, quotes and signatures.
     Text-only decoration avoids painting the description's trailing blank
     line. Local fonts only: no external font downloads. */
  td.bodyline > table:first-of-type span.gen:not(:has(a, img), .mainmenu, .mainmenu *, .postbody, .postbody *, .quote, .quote *, .signature, .signature *) {
    color: #D5A6FF !important;
    font-family: "Palatino Linotype", "Book Antiqua", Palatino, "URW Palladio L", Georgia, serif !important;
    font-size: 18px !important;
    font-weight: 600 !important;
    letter-spacing: 0.035em !important;
    line-height: 1.55 !important;
    background-color: transparent !important;
    border-radius: 0 !important;
    padding: 0 !important;
    box-shadow: none !important;
    text-shadow: -1px -1px 1px #030711, 1px -1px 1px #030711,
      -1px 1px 1px #030711, 1px 1px 1px #030711,
      0 2px 4px #000, 0 0 8px #bca0d999 !important;
  }

  /* FORUMOTION TOOLBAR — arcane metal, v1.2.0.
     Reuse the engraved title artwork directly, without large CSS variables.
     Keep the toolbar's native height, fixed positioning, icon sprites,
     dropdown behaviour and click targets. No overlays or pseudo-elements.
  */
  #fa_toolbar {
    background-color: #0b111e !important;
    background-image:
      linear-gradient(to bottom, #b6a4cd26 0%, #102337b3 44%, #080d19d9 52%, #152033b3 100%),
      url("data:image/png;base64,") !important;
    background-size: 100% 100%, 640px 100% !important;
    background-position: center, center !important;
    background-repeat: no-repeat, repeat-x !important;
    border-color: #a995af !important;
    box-shadow: inset 0 1px 0 #e2cbff80, inset 0 2px 0 #ffffff12,
      inset 0 -1px 0 #b69ac08c, inset 0 -2px 0 #07101c,
      0 3px 9px #00000099, 0 1px 8px #6c79ba40 !important;
    color: #e5d7f4 !important;
  }

  #fa_toolbar :is(#fa_left, #fa_right, #fa_share, #fa_search) {
    background-color: transparent !important;
    color: #d8c6e9 !important;
  }

  #fa_toolbar a:not(#fa_menulist a, #notif_list a) {
    color: #dfcef2 !important;
    text-shadow: 0 1px 2px #000, 0 0 5px #9181b24d !important;
  }
  #fa_toolbar a:hover:not(#fa_menulist a, #notif_list a) {
    color: #f3b7df !important;
    text-shadow: 0 1px 2px #000, 0 0 7px #b84f9e66 !important;
  }

  /* Search well: lighting creates depth without resizing the input. */
  #fa_toolbar #fa_search {
    border-radius: 6px !important;
    box-shadow: inset 0 2px 5px #000000b3, 0 1px 0 #c5aed44d !important;
  }
  #fa_toolbar #fa_textarea {
    background-color: #080e19 !important;
    color: #e8def3 !important;
    border-color: #756586 !important;
    border-radius: 5px !important;
    box-shadow: inset 0 2px 4px #00000099 !important;
  }
  #fa_toolbar #fa_search:focus-within {
    box-shadow: inset 0 2px 5px #00000099, 0 0 0 1px #94cef5,
      0 0 8px #618cdf66 !important;
  }

  #fa_toolbar :is(#fa_welcome, #fa_notifications) {
    background-color: #111b2b !important;
    background-image: linear-gradient(#31405399, #151d2da6 48%, #0d1423cc 52%, #1b2032b3) !important;
    border-radius: 4px !important;
    box-shadow: inset 0 1px 0 #cbb4dd4d, inset 0 -1px 0 #020710,
      0 1px 3px #00000066 !important;
  }
  #fa_toolbar :is(#fa_welcome, #fa_notifications):hover {
    background-image: linear-gradient(#49364f, #201a30) !important;
    box-shadow: inset 0 1px 0 #e0b8ee80, inset 0 -1px 0 #020710,
      0 0 7px #a91d6b40 !important;
  }
  #fa_toolbar :is(#fa_welcome, #fa_notifications):active {
    box-shadow: inset 0 2px 4px #000000b3 !important;
  }

  /* Dropdowns remain opaque and readable over the artwork. */
  #fa_toolbar :is(#fa_menulist, #notif_list) {
    background-color: #101827 !important;
    background-image: none !important;
    border-color: #8a739c !important;
    color: #e5d7f4 !important;
    box-shadow: inset 0 1px 0 #d4bce44d, 0 8px 20px #00000099 !important;
  }
  #fa_toolbar :is(#fa_menulist, #notif_list) li {
    background-color: #101827 !important;
    border-color: #354157 !important;
    color: #e5d7f4 !important;
  }
  #fa_toolbar :is(#fa_menulist, #notif_list) a {
    color: #a8d9f4 !important;
  }
  #fa_toolbar :is(#fa_menulist, #notif_list) li:hover {
    background-color: #28243c !important;
  }
  #fa_toolbar :is(#fa_menulist, #notif_list) a:hover {
    color: #f3b7df !important;
  }
  #fa_toolbar :is(a, input, button):focus-visible {
    outline: 2px solid #a6d9ff !important;
    outline-offset: -2px !important;
  }

  /* ARCANE SCROLLBARS — v1.2.2
     The page and nested scrollable elements share the same finish.
     Native overflow, scroll behaviour and resizing remain unchanged.
     Honour operating-system forced colours. No images or scripts needed.
  */
  @media (forced-colors: none) {
    /* Firefox colour fallback. Property-based checks also work with older
       Stylus validators that reject the selector() feature-query syntax. */
    @supports (-moz-appearance: none) {
      * {
        scrollbar-color: #8e9fca #080e18 !important;
        scrollbar-width: auto !important;
      }
    }

    @supports not (-moz-appearance: none) {
      /* Non-auto standard properties override decorative scrollbar rules
         in Chromium, so reset just those two properties in this branch. */
      * {
        scrollbar-color: auto !important;
        scrollbar-width: auto !important;
      }
      ::-webkit-scrollbar {
        width: 14px !important;
        height: 14px !important;
        background-color: #080e18 !important;
      }
      ::-webkit-scrollbar-track {
        background-color: #080e18 !important;
        border-radius: 8px !important;
        box-shadow: inset 1px 0 3px #000000cc, inset -1px 0 0 #a995af33 !important;
      }
      ::-webkit-scrollbar-thumb {
        background-color: #668faf !important;
        background-image: linear-gradient(90deg, #aa98c4 0%, #779dbd 22%, #416b90 52%, #6288aa 78%, #a995af 100%) !important;
        border: 2px solid #080e18 !important;
        border-radius: 9px !important;
        background-clip: padding-box !important;
        min-height: 36px !important;
        min-width: 36px !important;
        box-shadow: inset 0 1px 0 #e4d4ff99, inset 0 -1px 0 #122437 !important;
      }
      ::-webkit-scrollbar-thumb:horizontal {
        background-image: linear-gradient(180deg, #aa98c4 0%, #779dbd 22%, #416b90 52%, #6288aa 78%, #a995af 100%) !important;
      }
      ::-webkit-scrollbar-thumb:hover {
        background-color: #b57cb5 !important;
        background-image: linear-gradient(90deg, #dab7ed, #ad83bd 25%, #805887 55%, #bd8cba 80%, #e0b9e6) !important;
        box-shadow: inset 0 1px 0 #f5dcffb3, inset 0 -1px 0 #3b203e !important;
      }
      ::-webkit-scrollbar-thumb:active {
        background-color: #c493dc !important;
        background-image: linear-gradient(90deg, #ac83c5, #d5a6ff 48%, #9476b8) !important;
        box-shadow: inset 0 1px 3px #25153099 !important;
      }
      ::-webkit-scrollbar-corner {
        background-color: #080e18 !important;
      }
    }
  }

  /* MULTI-QUOTE SELECTED IMAGE FIX — v1.2.3
     Forumotion toggles .selected on the original clickable image.
     Replace only its rendered graphic; retain src, id, alt and onclick.
     Embedded artwork avoids the unavailable remote selected-state asset.
     Removing .selected automatically restores the site's normal image. */
  img[id^="post_mq"].selected {
    content: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22117%22%20height%3D%2218%22%20viewBox%3D%220%200%20117%2018%22%3E%3Cdefs%3E%3ClinearGradient%20id%3D%22metal%22%20x2%3D%220%22%20y2%3D%221%22%3E%3Cstop%20stop-color%3D%22%23725780%22%2F%3E%3Cstop%20offset%3D%22.45%22%20stop-color%3D%22%23382d4c%22%2F%3E%3Cstop%20offset%3D%221%22%20stop-color%3D%22%231b2438%22%2F%3E%3C%2FlinearGradient%3E%3C%2Fdefs%3E%3Crect%20x%3D%22.5%22%20y%3D%22.5%22%20width%3D%22116%22%20height%3D%2217%22%20rx%3D%224%22%20fill%3D%22url%28%23metal%29%22%20stroke%3D%22%23d5a6ff%22%2F%3E%3Cpath%20d%3D%22M3%205V4Q3%202%205%202H112%22%20fill%3D%22none%22%20stroke%3D%22%23f3e4ff%22%20stroke-opacity%3D%22.4%22%2F%3E%3Cpath%20d%3D%22m8%209%203%203%205-6%22%20fill%3D%22none%22%20stroke%3D%22%23d5a6ff%22%20stroke-width%3D%222%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%2F%3E%3Ctext%20x%3D%2265%22%20y%3D%2212.5%22%20text-anchor%3D%22middle%22%20font-family%3D%22Arial%2Csans-serif%22%20font-size%3D%2211%22%20font-weight%3D%22700%22%20fill%3D%22%23f3e4ff%22%3ESelected%3C%2Ftext%3E%3C%2Fsvg%3E") !important;
    width: 117px !important;
    height: 18px !important;
    min-width: 117px !important;
    min-height: 18px !important;
    max-width: 117px !important;
    max-height: 18px !important;
    box-sizing: border-box !important;
    padding: 0 !important;
    border: 0 !important;
    background: transparent !important;
    object-fit: contain !important;
    vertical-align: middle !important;
    cursor: pointer !important;
  }

  /* EDITOR TOOL GROUPS — v1.2.4
     Light metal surfaces keep the original dark and coloured icon sprites
     readable. Scope decoration to toolbar groups, not the editable content. */
  .sceditor-container .sceditor-toolbar {
    background: linear-gradient(180deg, #27394c, #142130) !important;
    border: 1px solid #7d91ad !important;
    border-bottom-color: #a995bf !important;
    border-radius: 7px 7px 0 0 !important;
    padding: 5px !important;
    box-shadow: inset 0 1px 0 #c9dcec66, 0 2px 5px #00000066 !important;
  }
  .sceditor-container .sceditor-toolbar .sceditor-group {
    background: linear-gradient(180deg, #d0dce8 0%, #afc0d2 48%, #94aac0 100%) !important;
    border: 1px solid #d5c0eb !important;
    border-bottom-color: #7085a0 !important;
    border-radius: 5px !important;
    padding: 2px !important;
    margin: 2px 4px 2px 0 !important;
    box-shadow: inset 0 1px 0 #ffffffb3, inset 0 -1px 0 #52678099,
                0 2px 3px #00000080 !important;
  }
  .sceditor-container .sceditor-toolbar .sceditor-button {
    background: transparent !important;
    border-radius: 3px !important;
    box-shadow: none !important;
  }
  .sceditor-container .sceditor-toolbar .sceditor-button:hover {
    background: linear-gradient(180deg, #f0e3ff, #c1a8dd) !important;
    box-shadow: inset 0 0 0 1px #795999, 0 0 4px #d5a6ff99 !important;
  }
  .sceditor-container .sceditor-toolbar .sceditor-button.active {
    background: linear-gradient(180deg, #b79bcf, #ead7ff) !important;
    box-shadow: inset 0 0 0 2px #70508d, inset 0 2px 4px #35214666 !important;
  }
  .sceditor-container .sceditor-toolbar .sceditor-button:focus-visible {
    outline: 2px solid #563673 !important;
    outline-offset: -2px !important;
  }
  .sceditor-container .sceditor-toolbar .sceditor-button.disabled {
    background: transparent !important;
    opacity: .45 !important;
    box-shadow: none !important;
  }

  /* ARCANE SANCTUARY BANNER — v1.2.6
     Embedded original PNG. Replaces only the displayed logo image;
     the existing link, alt text and site markup are preserved.
     Centred, capped at 720px wide (about 320px tall), and responsive. */
  img#i_logo {
    content: url("data:image/png;base64,") !important;
    display: block !important;
    width: 100% !important;
    max-width: 720px !important;
    min-width: 0 !important;
    height: auto !important;
    max-height: none !important;
    aspect-ratio: 1882 / 836 !important;
    object-fit: contain !important;
    box-sizing: border-box !important;
    margin: 1px auto !important;
    padding: 0 !important;
    border: 0 !important;
  }

  /* SINGLE-ROW EDITOR TOOLBAR — v1.2.7
     Keep groups and buttons intact. Narrow editors scroll horizontally
     instead of wrapping, shrinking icons or expanding the page width. */
  .sceditor-container .sceditor-toolbar {
    display: flex !important;
    flex-flow: row nowrap !important;
    align-items: center !important;
    justify-content: flex-start !important;
    box-sizing: border-box !important;
    width: 100% !important;
    max-width: 100% !important;
    min-width: 0 !important;
    white-space: nowrap !important;
    overflow-x: auto !important;
    overflow-y: hidden !important;
  }
  .sceditor-container .sceditor-toolbar .sceditor-group {
    display: flex !important;
    flex-flow: row nowrap !important;
    align-items: center !important;
    flex: 0 0 auto !important;
    float: none !important;
    white-space: nowrap !important;
  }
  .sceditor-container .sceditor-toolbar .sceditor-button {
    flex: 0 0 auto !important;
    float: none !important;
  }
}
